resp = requests.post('http://localhost/v1/chat-messages',
    headers={'Authorization': 'Bearer ' + APP_KEY},
    json={'inputs': {}, 'query': '讲个笑话', 'response_mode': 'streaming', 'user': 'u1'},
    stream=True)
for line in resp.iter_lines():
    if line:
        print(line.decode('utf-8'))  # 每行形如 data: {"event":"message","answer":"..."}
